#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_W 128
#define SCREEN_H 64
#define OLED_ADDR 0x3C
Adafruit_SSD1306 display(SCREEN_W, SCREEN_H, &Wire, -1);

// Wiring: probe AOUT -> D2 (GPIO4, ADC1); probe VCC -> D10 (GPIO10) so it is off in sleep, GND -> GND.
// Probe output falls when wet (dry ~2700, wet ~1200 on ESP32-C3 ADC): higher ADC = drier.
// Button SW1: D1 (GPIO3) to GND with internal pull-up, LOW when pressed.
// Display: SDA=D4(GPIO6), SCL=D5(GPIO7), VCC=V3V3.
const int PIN_PROBE = D2;
const int PIN_PROBE_PWR = D10;
const int PIN_BUTTON = D1;

const int ADC_DRY = 2700;
const int ADC_WET = 1200;

int readProbe() {
  digitalWrite(PIN_PROBE_PWR, HIGH);
  delay(100);
  long sum = 0;
  for (int i = 0; i < 16; i++) { sum += analogRead(PIN_PROBE); delay(10); }
  digitalWrite(PIN_PROBE_PWR, LOW);
  return sum / 16;
}

void showReading(int adc, int pct, const char* hint) {
  display.clearDisplay();
  display.setTextSize(2);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.print(pct);
  display.print("%");
  display.setTextSize(1);
  display.setCursor(0, 24);
  display.print(hint);
  display.setCursor(0, 40);
  display.print("ADC:");
  display.print(adc);
  display.setCursor(0, 52);
  display.print("press=read");
  display.display();
}

void setup() {
  pinMode(PIN_BUTTON, INPUT_PULLUP);
  pinMode(PIN_PROBE, INPUT);
  pinMode(PIN_PROBE_PWR, OUTPUT);
  Wire.begin();
  bool dispOk = display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR);
  int adc = readProbe();
  // re-enable power for possible re-reads while awake
  digitalWrite(PIN_PROBE_PWR, HIGH);
  int pct = constrain(map(adc, ADC_DRY, ADC_WET, 0, 100), 0, 100);
  const char* hint = (pct < 30) ? "WATER ME" : (pct < 60) ? "ok" : "too wet";
  if (dispOk) showReading(adc, pct, hint);
  unsigned long t0 = millis();
  int lastBtn = HIGH;
  while (millis() - t0 < 15000) {
    int b = digitalRead(PIN_BUTTON);
    if (lastBtn == HIGH && b == LOW && dispOk) {
      int a2 = readProbe();
      digitalWrite(PIN_PROBE_PWR, HIGH);
      int p2 = constrain(map(a2, ADC_DRY, ADC_WET, 0, 100), 0, 100);
      const char* h2 = (p2 < 30) ? "WATER ME" : (p2 < 60) ? "ok" : "too wet";
      showReading(a2, p2, h2);
      t0 = millis();
    }
    lastBtn = b;
    delay(30);
  }
  digitalWrite(PIN_PROBE_PWR, LOW);
  pinMode(PIN_PROBE_PWR, OUTPUT);
  digitalWrite(PIN_PROBE_PWR, LOW);
  if (dispOk) display.ssd1306_command(SSD1306_DISPLAYOFF);
  esp_deep_sleep_enable_gpio_wakeup(1ULL << 3, ESP_GPIO_WAKEUP_GPIO_LOW);
  esp_sleep_enable_timer_wakeup(10ULL * 60ULL * 1000000ULL);
  esp_deep_sleep_start();
}

void loop() {}

